source3='''def transform(grid):
    out = [row[:] for row in grid]
    fours = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    sixes = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 6]
    if not fours or not sixes:
        return out
    top = min(r for r, _ in fours)
    bottom = max(r for r, _ in fours)
    left = min(c for _, c in fours)
    right = max(c for _, c in fours)
    marker_top = min(r for r, _ in sixes)
    marker_bottom = max(r for r, _ in sixes)
    marker_left = min(c for _, c in sixes)
    marker_right = max(c for _, c in sixes)
    marker_width = marker_right - marker_left + 1
    marker_height = marker_bottom - marker_top + 1
    for r, c in sixes:
        out[r][c] = 0
    if marker_width > marker_height:
        center_r = sum(r for r, _ in fours) / len(fours)
        if center_r >= (len(grid) - 1) / 2:
            for r, c in fours:
                target_r = top - 1 - (r - top)
                if target_r >= 0:
                    out[target_r][c] = 4
        else:
            for r, c in fours:
                target_r = bottom + 1 + (bottom - r)
                if target_r < len(out):
                    out[target_r][c] = 4
    else:
        top_row = [c for r, c in sixes if r == marker_top]
        bottom_row = [c for r, c in sixes if r == marker_bottom]
        copy_right = len(top_row) >= len(bottom_row)
        if copy_right:
            for r, c in fours:
                target_c = right + 1 + (right - c)
                if target_c < len(out[0]):
                    out[r][target_c] = 4
        else:
            for r, c in fours:
                target_c = left - 1 - (c - left)
                if target_c >= 0:
                    out[r][target_c] = 4
    return out
'''
